solution.code:
#include <stdio.h>

enum { READ = 4, WRITE = 2, EXEC = 1 };

int main() {
    int perms = READ | EXEC;
    printf("%s\n", (perms & WRITE) ? "can write" : "cannot write");
    if (perms & READ) {
        printf("can read\n");
    }
    return 0;
}
